import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_runtime.h>
#include <cooperative_groups.h>

namespace cg = cooperative_groups;

#define BLOCK_THREADS 256

// Fused LayerNorm, restructured into two kernels for much higher occupancy.
// Optimization: split-row reduction + grid-stride normalize. The previous
// design launched only one thread block per row (16 blocks for the target
// shape), badly underutilizing the GPU. Kernel 1 (stats) splits each row
// across many blocks; each block reduces its slice (double precision +
// warp/shared reduction) and atomically accumulates the partial
// (sum, sum of squares) into a tiny global stats buffer. Kernel 2
// (normalize) is a fully parallel grid-stride pass over the whole tensor
// that derives mean/rstd from the stats on the fly.
__global__ void layernorm_stats_kernel(const float4* __restrict__ x,
                                       double* __restrict__ stats,
                                       int nv) {
    long row   = blockIdx.x;
    int  split = blockIdx.y;
    long chunk = ((long)nv + gridDim.y - 1) / gridDim.y;
    long begin = (long)split * chunk;
    long end   = begin + chunk;
    if (end > (long)nv) end = (long)nv;
    const float4* xr = x + row * (long)nv;
    // Local partial sums (double precision for accuracy).
    double s = 0.0, sq = 0.0;
    for (long i = begin + threadIdx.x; i < end; i += BLOCK_THREADS) {
        float4 v = __ldg(xr + i);
        s  += (double)v.x + (double)v.y + (double)v.z + (double)v.w;
        sq += (double)v.x * v.x + (double)v.y * v.y +
              (double)v.z * v.z + (double)v.w * v.w;
    }
    // Block-wide reduction of (sum, sum of squares).
    const unsigned full_mask = 0xffffffffu;
    for (int offset = 16; offset > 0; offset >>= 1) {
        s  += __shfl_down_sync(full_mask, s, offset);
        sq += __shfl_down_sync(full_mask, sq, offset);
    }
    __shared__ double ss[BLOCK_THREADS / 32];
    __shared__ double ssq[BLOCK_THREADS / 32];
    const int lane = threadIdx.x & 31;
    const int warp = threadIdx.x >> 5;
    if (lane == 0) {
        ss[warp]  = s;
        ssq[warp] = sq;
    }
    __syncthreads();
    if (warp == 0) {
        s  = (lane < (BLOCK_THREADS / 32)) ? ss[lane]  : 0.0;
        sq = (lane < (BLOCK_THREADS / 32)) ? ssq[lane] : 0.0;
        for (int offset = (BLOCK_THREADS / 32) / 2; offset > 0; offset >>= 1) {
            s  += __shfl_down_sync(full_mask, s, offset);
            sq += __shfl_down_sync(full_mask, sq, offset);
        }
        if (lane == 0) {
            atomicAdd(stats + row * 2,     s);
            atomicAdd(stats + row * 2 + 1, sq);
        }
    }
}
// Tiny finalize pass: derive per-row (mean, rstd) once from the global
// stats buffer, removing the expensive per-element double-precision
// division + rsqrt from the normalize pass below.
__global__ void layernorm_finalize_kernel(const double* __restrict__ stats,
                                          double* __restrict__ mr,
                                          long rows, long n, float eps) {
    long row = (long)blockIdx.x * blockDim.x + threadIdx.x;
    if (row < rows) {
        double sum  = __ldg(stats + row * 2);
        double sumq = __ldg(stats + row * 2 + 1);
        double mean = sum / (double)n;
        double var  = sumq / (double)n - mean * mean;
        mr[row * 2]     = mean;
        mr[row * 2 + 1] = rsqrt(var + (double)eps);
    }
}
// Pass 2: fully parallel normalize. Each block owns a column slice and
// reuses that weight/bias slice across all rows in registers, removing
// rows-duplicate global loads of the large affine parameters. The per-row
// (mean, rstd) factors are precomputed by the finalize kernel, so the hot
// loop only needs one cached double2 load per row instead of computing
// double-precision division and rsqrt for every single element.
__global__ void layernorm_normalize_kernel(const float4* __restrict__ x,
                                           const float4* __restrict__ w,
                                           const float4* __restrict__ b,
                                           float4* __restrict__ y,
                                           const double* __restrict__ mr,
                                           int nv, long rows) {
    long stride = (long)gridDim.x * BLOCK_THREADS;
    for (long i = (long)blockIdx.x * BLOCK_THREADS + threadIdx.x; i < (long)nv; i += stride) {
        float4 wv = __ldg(w + i);
        float4 bv = __ldg(b + i);
        for (long row = 0; row < rows; ++row) {
            double mean = __ldg(mr + row * 2);
            double rstd = __ldg(mr + row * 2 + 1);
            long off = row * (long)nv + i;
            float4 v = __ldcs(x + off);
            float4 o;
            o.x = (float)(((double)v.x - mean) * rstd) * wv.x + bv.x;
            o.y = (float)(((double)v.y - mean) * rstd) * wv.y + bv.y;
            o.z = (float)(((double)v.z - mean) * rstd) * wv.z + bv.z;
            o.w = (float)(((double)v.w - mean) * rstd) * wv.w + bv.w;
            __stcs(y + off, o);
        }
    }
}
torch::Tensor layernorm_forward(torch::Tensor x, torch::Tensor w,
                                torch::Tensor b, double eps) {
    TORCH_CHECK(x.is_cuda() && x.scalar_type() == torch::kFloat32,
                "input must be a CUDA float tensor");
    auto xc = x.contiguous();
    auto wc = w.contiguous();
    auto bc = b.contiguous();
    auto y  = torch::empty_like(xc);
    long n    = wc.numel();
    long rows = xc.numel() / n;
    TORCH_CHECK(n % 4 == 0, "normalized size must be divisible by 4");
    int nv = (int)(n / 4);
    const float4* xp = reinterpret_cast<const float4*>(xc.data_ptr<float>());
    const float4* wp = reinterpret_cast<const float4*>(wc.data_ptr<float>());
    const float4* bp = reinterpret_cast<const float4*>(bc.data_ptr<float>());
    float4* yp       = reinterpret_cast<float4*>(y.data_ptr<float>());
    float epsf       = (float)eps;
    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    // Global (sum, sum of squares) stats, one double2 per row.
    auto stats = torch::zeros({rows, 2},
                 torch::TensorOptions().dtype(torch::kFloat64).device(xc.device()));
    double* sp = stats.data_ptr<double>();
    // Pick a split factor so that rows*splits blocks fill the GPU.
    int sms = at::cuda::getCurrentDeviceProperties()->multiProcessorCount;
    long splits = ((long)sms * 8) / (rows > 0 ? rows : 1);
    if (splits < 1)  splits = 1;
    if (splits > 64) splits = 64;
    long min_chunk  = (long)BLOCK_THREADS * 4;
    long max_splits = ((long)nv + min_chunk - 1) / min_chunk;
    if (max_splits < 1) max_splits = 1;
    if (splits > max_splits) splits = max_splits;
    dim3 gridA((unsigned)rows, (unsigned)splits);
    layernorm_stats_kernel<<<gridA, dim3(BLOCK_THREADS), 0, stream>>>(xp, sp, nv);
    // Precompute per-row (mean, rstd) once so the normalize pass avoids
    // the expensive per-element double-precision division and rsqrt.
    auto mr = torch::empty({rows, 2},
                 torch::TensorOptions().dtype(torch::kFloat64).device(xc.device()));
    double* mrp = mr.data_ptr<double>();
    long fblocks = (rows + BLOCK_THREADS - 1) / BLOCK_THREADS;
    if (fblocks < 1) fblocks = 1;
    layernorm_finalize_kernel<<<dim3((unsigned)fblocks), dim3(BLOCK_THREADS), 0, stream>>>(
        sp, mrp, rows, n, epsf);
    // Launch more normalize blocks for higher memory-level parallelism;
    // the kernel still grid-strides if nv exceeds the launch cap.
    const long norm_chunk = (long)BLOCK_THREADS;
    long nblocks = ((long)nv + norm_chunk - 1) / norm_chunk;
    if (nblocks < 1) nblocks = 1;
    if (nblocks > 65535) nblocks = 65535;
    dim3 gridB((unsigned)nblocks);
    layernorm_normalize_kernel<<<gridB, dim3(BLOCK_THREADS), 0, stream>>>(
        xp, wp, bp, yp, mrp, nv, rows);
    return y;
}
"""

cpp_src = ("torch::Tensor layernorm_forward(torch::Tensor x, torch::Tensor w, "
           "torch::Tensor b, double eps);")

_mod = load_inline(
    name="layernorm_cuda_ext",
    cpp_sources=cpp_src,
    cuda_sources=cuda_src,
    functions=["layernorm_forward"],
    verbose=False,
    extra_cuda_cflags=["-O3"],
)


class ModelNew(nn.Module):
    """
    LayerNorm implemented with a custom fused CUDA kernel.
    """
    def __init__(self, normalized_shape: tuple):
        super(ModelNew, self).__init__()
        self.normalized_shape = tuple(normalized_shape)
        self.weight = nn.Parameter(torch.ones(self.normalized_shape))
        self.bias = nn.Parameter(torch.zeros(self.normalized_shape))
        self.eps = 1e-5

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return _mod.layernorm_forward(x, self.weight, self.bias, self.eps)

